aaa-pattern.example:
[Fact]
public void CalculateTotalPrice_WithDiscount_AppliesDiscountCorrectly()
{
    // Arrange
    var cart = new ShoppingCart();
    cart.AddItem(new Product("Widget", price: 100m), quantity: 2);
    var discount = new PercentageDiscount(10);

    // Act
    var total = cart.CalculateTotalPrice(discount);

    // Assert
    Assert.Equal(180m, total);
}

it('should return the full name when first and last name are provided', () => {
    // Arrange
    const person = new Person({ firstName: 'John', lastName: 'Doe' });

    // Act
    const fullName = person.getFullName();

    // Assert
    expect(fullName).toBe('John Doe');
});

builder-pattern.example:
// Builder with defaults
var order = new OrderBuilder()
    .WithCustomer(customer)
    .WithItem("Widget", quantity: 2, price: 50m)
    .Build();

// Only the test-relevant fields are set; everything else is a safe default
var overdueOrder = new OrderBuilder()
    .WithStatus(OrderStatus.Pending)
    .WithCreatedAt(DateTime.UtcNow.AddDays(-30))
    .Build();

object-mother.example:
public static class TestOrders
{
    public static Order NewPendingOrder() => new Order { Status = OrderStatus.Pending, ... };
    public static Order NewShippedOrder() => new Order { Status = OrderStatus.Shipped, ... };
    public static Order NewCancelledOrder() => new Order { Status = OrderStatus.Cancelled, ... };
}

avoid-magic-numbers.example:
// Bad — why 180?
Assert.Equal(180m, cart.Total);

// Good — the calculation is visible
const decimal itemPrice = 100m;
const int quantity = 2;
const decimal discountRate = 0.10m;
var expected = itemPrice * quantity * (1 - discountRate);
Assert.Equal(expected, cart.Total);
